"""Twenty challenging self-contained mathematics/probability problems."""
def add_items(add):
    add('Q11','mathematics','אינטגרל לא אמיתי','Evaluate the convergent improper integral from x=0 to infinity of ln(x)/(1+x)^3 dx.','חשב את האינטגרל מ־0 עד אינסוף של ln(x)/(1+x)^3.','-1/2',['0','1/2','-1'],'נגזור לפי a את B(a,3−a) ב־a=1. B(1,2)=1/2 והפרש דיגמא ψ(1)−ψ(2)=−1, ולכן ‎−1/2.')
    add('Q12','mathematics','דטרמיננטה מסדר 12','A 12 by 12 matrix has 3 on its main diagonal, -1 immediately above and below that diagonal, and 0 elsewhere. What is its determinant?','מטריצה מסדר 12 כוללת 3 באלכסון הראשי, ‎−1 בשני האלכסונים הצמודים ו־0 בשאר המקומות. מה הדטרמיננטה?','121393',['75025','196418','317811'],'Dn=3D(n−1)−D(n−2), עם D0=1,D1=3. זוהי F(2n+2), ולכן D12=F26=121393.')
    add('Q13','mathematics','קונגרואנציה','What is the smallest integer x strictly greater than 1 such that x^2 is congruent to 1 modulo 1001?','מהו השלם הקטן ביותר x הגדול ממש מ־1 כך ש־x² שקול ל־1 מודולו 1001?','155',['77','143','274'],'1001=7×11×13. לפי משפט השאריות הסיני השורשים בתחום הם 1,155,274,428,573,727,846,1000. הקטן הבא הוא 155.')
    add('Q14','mathematics','חלוקות על','Seven distinct objects are assigned to three labeled boxes. Every box must receive at least one object. How many assignments are possible?','מחלקים 7 עצמים שונים ל־3 קופסאות מסומנות, בלי להשאיר קופסה ריקה. כמה חלוקות אפשריות?','1806',['2187','1728','2100'],'הכלה והפרדה: 3^7−3×2^7+3=1806.')
    add('Q15','mathematics','רקורסיה עם שורש כפול','Let a0=0, a1=1 and an=4*a(n-1)-4*a(n-2) for n>=2. What is a15?','נתון a0=0,a1=1 והכלל an=4*a(n−1)−4*a(n−2). מהו a15?','245760',['229376','262144','491520'],'הפולינום האופייני (r−2)². התנאים נותנים an=n×2^(n−1), ולכן a15=245760.')
    add('Q16','mathematics','שורשי יחידה','Let zeta=exp(2*pi*i/17), a primitive 17th root of unity. Evaluate the sum over k=1,...,16 of 1/(1-zeta^k).','נתון zeta=exp(2*pi*i/17). חשב את סכום 1/(1−zeta^k) עבור k=1 עד 16.','8',['0','16','17/2'],'מצמידים k ו־17−k. כל זוג נותן 1/(1−z)+1/(1−1/z)=1. שמונה זוגות נותנים 8.')
    add('Q17','mathematics','אופטימיזציה של דיסקרימיננטה','Real numbers x,y,z satisfy x+y+z=0 and x^2+y^2+z^2=6. What is the maximum of (x-y)^2*(y-z)^2*(z-x)^2?','ממשיים x,y,z מקיימים x+y+z=0 ו־x²+y²+z²=6. מה המקסימום של (x−y)²(y−z)²(z−x)²?','108',['54','216','27'],'xy+yz+zx=−3. דיסקרימיננטת t³−3t−xyz היא 108−27(xyz)². המקסימום 108 מושג ב־(√3,0,−√3).')
    add('Q18','mathematics','טור אינסופי','Evaluate the infinite sum over n=1,2,... of 1/(n^2*(n+1)^2).','חשב את הטור האינסופי סכום 1/[n²(n+1)²] עבור n החל מ־1.','pi^2/3 - 3',['pi^2/6 - 1','pi^2/3 - 2','2 - pi^2/6'],'מפרקים ל־1/n²+1/(n+1)²−2/[n(n+1)]. הסכום 2ζ(2)−3=π²/3−3.')
    add('Q19','mathematics','עצים פורשים','How many spanning trees does the complete bipartite graph K(4,5) have? Vertices are labeled; every vertex in one part is adjacent to every vertex in the other part.','כמה עצים פורשים יש בגרף הדו־צדדי המלא K(4,5), שכל קודקודיו מסומנים?','32000',['20000','62500','102400'],'ממשפט המטריצה־עץ, עבור K(m,n) המספר m^(n−1)n^(m−1). לכן 4⁴×5³=32000.')
    add('Q20','mathematics','סכום על שורשי פולינום','Let r1,...,r5 be all complex roots, counted with multiplicity, of p(t)=t^5-3*t+1. Evaluate the sum of 1/(rj-1)^2 over j=1,...,5.','r1 עד r5 הם שורשי t^5−3t+1 במרוכבים, כולל ריבוי. חשב את סכום 1/(rj−1)².','24',['16','20','-24'],'מ־p\u0027/p=Σ1/(t−rj), הסכום המבוקש הוא (p\u0027/p)²−p\u0027\u0027/p ב־t=1. p=−1,p\u0027=2,p\u0027\u0027=20, לכן 24.')
    add('Q21','mathematics','אינטגרל כפול','Evaluate the improper double integral over 0<x<1 and 0<y<1 of ln(x)*ln(y)/(1-x*y) dx dy.','חשב את האינטגרל הכפול בריבוע היחידה של ln(x)*ln(y)/(1−xy).','pi^4/90',['pi^2/6','pi^4/45','1'],'מפתחים 1/(1−xy)=Σ(xy)^n. כל איבר תורם 1/(n+1)^4; הסכום ζ(4)=π⁴/90.')
    add('Q22','mathematics','מסלולי סריג ללא מגע פנימי','Count lattice paths from (0,0) to (8,8) using only unit east and north steps, staying strictly below y=x at every intermediate vertex. Start and end are the only permitted contacts with y=x.','כמה מסלולי סריג מ־(0,0) ל־(8,8), בצעדי מזרח וצפון בלבד, נשארים ממש מתחת ל־y=x בכל קודקוד ביניים?','429',['1430','3432','715'],'הצעד הראשון מזרח והאחרון צפון. הסרתם והזזה נותנות מסלול קטלן מסדר 7: C7=binomial(14,7)/8=429.')
    add('Q23','probability','המתנה לתבנית חופפת','Independently flip a fair coin until the consecutive pattern HTHTH appears for the first time. H means heads and T tails. What is the expected total number of flips, counting the final five flips?','מטילים מטבע הוגן עד ההופעה הראשונה של HTHTH. מה תוחלת מספר ההטלות הכולל, כולל הרצף האחרון?','42',['32','40','62'],'חפיפות תחילית–סופית באורכים 1,3,5 נותנות תוחלת 2¹+2³+2⁵=42. מאומת גם במשוואות מצבי תחילית.')
    add('Q24','probability','הסתברות גאומטרית מותנית','X and Y are independent Uniform(0,1) variables. What is P(X^2+Y^2<1 | X+Y>1)?','X,Y בלתי תלויים ואחידים ב־(0,1). מה P(X²+Y²<1 בהינתן X+Y>1)?','pi/2 - 1',['pi/4','1/2','2 - pi/2'],'שטח רבע העיגול מעל הישר π/4−1/2. שטח התחום המותנה 1/2. היחס π/2−1.')
    add('Q25','probability','חיזוי בייסיאני','A coin has a fixed but unknown heads probability p sampled from Uniform(0,1). Conditional on p, flips are independent. You observe 7 heads and 2 tails in 9 flips. What is the posterior predictive probability that the next 3 flips are all heads?','סיכוי קבוע p ל־H נבחר מראש אחיד ב־(0,1). אחרי 7 H ו־2 T, מה ההסתברות המנבאת ששלוש ההטלות הבאות יהיו כולן H?','60/143',['343/729','49/81','12/55'],'ההתפלגות המותנית Beta(8,3). מומנט שלישי: 8×9×10/(11×12×13)=60/143; אין להציב p=7/9.')
    add('Q26','probability','נקודות קבועות בפרמוטציה','Choose a permutation of 8 labeled elements uniformly from all 8! permutations. What is the probability of exactly 2 fixed points?','בוחרים פרמוטציה אחידה של 8 עצמים. מה ההסתברות לשתי נקודות קבועות בדיוק?','53/288',['53/144','1/2','265/20160'],'binomial(8,2)×D6/8!, עם D6=265, נותן 53/288.')
    add('Q27','probability','זמן פגיעה בשרשרת מרקוב','A Markov chain has states 0,1,2,3; 3 is absorbing. From 0 it moves to 1 surely; from 1 to 0 or 2 with probability 1/2 each; from 2 to 1 with probability 1/3 or to 3 with probability 2/3. Starting at 0, what is the expected number of transitions to first visit 3?','בשרשרת: 0→1 תמיד; 1→0 או 2 בחצי; 2→1 בשליש ו־2→3 בשני שלישים. 3 בולע. מה תוחלת מספר המעברים מ־0 עד 3?','7',['6','9','11/2'],'e0=1+e1; e1=1+(e0+e2)/2; e2=1+e1/3. e1=6 ולכן e0=7.')
    add('Q28','probability','חורבן המהמר','A random walk starts at integer 3. Independently each step goes up 1 with probability 3/5 or down 1 with probability 2/5. It stops at 0 or 7. What is the probability it stops at 7?','הילוך מתחיל ב־3, עולה יחידה בהסתברות 3/5 ויורד יחידה בהסתברות 2/5, עד 0 או 7. מה ההסתברות להגיע ל־7 קודם?','1539/2059',['3/7','27/35','1467/2059'],'פתרון h(i)=0.6h(i+1)+0.4h(i−1), h0=0,h7=1, הוא [1−(2/3)^i]/[1−(2/3)^7]. ב־i=3: 1539/2059.')
    add('Q29','probability','מומנט של מרחק בדיסקה','Choose X and Y independently and uniformly by area inside the unit disk in the plane. D is their Euclidean distance. What is E[D^4]?','בוחרים שתי נקודות בלתי תלויות ואחידות לפי שטח בדיסקת היחידה. אם D המרחק האוקלידי, מה E[D^4]?','5/3',['1','4/3','2'],'E[r²]=1/2,E[r⁴]=1/3,E[cosθ]=0,E[cos²θ]=1/2. פיתוח D⁴ נותן 2/3+1/2+1/2=5/3.')
    add('Q30','probability','ראשים במעגל','Ten fair independent coin flips are conditioned on exactly four heads. Arrange the ten positions in a circle, so positions 10 and 1 are adjacent. What is the conditional probability that no two heads are adjacent?','עשר הטלות מותנות בארבעה H בדיוק. המיקומים במעגל, כולל סמיכות 10 ו־1. מה ההסתברות שלא יהיו שני H סמוכים?','5/42',['1/6','1/7','5/21'],'מספר קבוצות ללא סמיכות במעגל: 10/6×binomial(6,4)=25. מחלקים ב־binomial(10,4)=210 לקבלת 5/42.')
